#pragma once
inline void historyTests(){
 auto s=std::make_shared<EditSession>();auto a=std::make_shared<noori::Audio>();a->sampleRate=48000;a->channels.resize(1,std::vector<float>(96000));a->channels[0][24000]=.8f;
 s->load([a]{return *a;},"History source",1234,noori::Timeline());waitSession(s);auto loaded=s->state();s->undo();check(!s->original&&s->audible.load()==nullptr,"Import undo restores empty session");s->redo();check(s->state()==loaded,"Import redo restores full source state");
 juce::Image mark(juce::Image::ARGB,8,4,true);mark.clear(mark.getBounds(),juce::Colours::blue);juce::MemoryOutputStream logoOut;juce::PNGImageFormat png;check(png.writeImageToStream(mark,logoOut),"Logo PNG fixture");auto logo=std::make_shared<juce::MemoryBlock>(logoOut.getMemoryBlock());s->change("Logo",[&]{s->logoPNG=logo;});s->undo();check(!s->logoPNG,"Logo undo");s->redo();check(s->logoPNG==logo,"Logo redo");
 const auto before=s->state();
 s->change("Settings",[&]{s->settings.division=16;s->settings.sensitivity=.8;s->settings.percussion=true;s->settings.maxStretch=1.5;s->exactBpm=false;});auto configured=s->state();s->undo();check(s->state()==before,"All detector and quantization settings undo together");s->redo();check(s->state()==configured,"All detector and quantization settings redo together");
 s->change("Theme / display",[&]{s->lightTheme=false;s->levelView=true;s->overlay=true;s->viewZoom=3;s->viewStart=.2;s->manualBpm=123;s->preset=2;s->audition=true;s->compare=true;});auto ui=s->state();s->undo();check(s->state()==configured,"Theme, listening, preset, BPM and zoom undo");s->redo();check(s->state()==ui,"Theme, listening, preset, BPM and zoom redo");
 auto archived=s->archive(true);auto saved=std::make_shared<EditSession>();saved->restore(archived.getData(),archived.getSize(),true);waitSession(saved);check(!saved->lightTheme&&saved->levelView&&saved->overlay&&saved->viewZoom==3&&saved->settings.percussion&&saved->manualBpm==123&&saved->logoPNG&&*saved->logoPNG==*logo,"Extended settings and theme persist in project state");
 s->loadProjectReference({{a,0,2,0}},"Reference fixture");waitSession(s);auto reference=s->state();s->undo();check(s->state()==ui,"Reference import undo restores previous settings and source");s->redo();check(s->state()==reference&&s->referenceAudio,"Reference redo restores waveform and attacks");
 s->anchorTo(5000);auto anchored=s->state();s->undo();check(s->state()==reference,"Origin and reference positions undo");s->redo();check(s->state()==anchored,"Origin and reference positions redo");
 s->addAttack(24000);waitSession(s);check(s->attacks.size()==1,"Manual attack added");auto marker=s->state();s->removeSelectedAttacks();waitSession(s);check(s->attacks.empty(),"Selected manual attack removed");s->undo();check(s->state()==marker,"Marker removal undo restores render and selection");s->redo();check(s->attacks.empty(),"Marker removal redo");
 auto failure=s->state();s->load([]()->noori::Audio{throw std::runtime_error("Fixture failure");},"Bad import",0,noori::Timeline());waitSession(s,false);check(s->state()==failure,"Failed import leaves complete prior state intact");
 s->change("Sensitivity",[&]{s->settings.sensitivity=.1;},true);s->change("Sensitivity",[&]{s->settings.sensitivity=.2;},true);s->undo();check(s->settings.sensitivity==failure.settings.sensitivity,"Continuous control changes coalesce into one undo");s->change("New branch",[&]{s->lightTheme=!s->lightTheme;});check(!s->canRedo(),"New setting edit clears redo branch");
 auto t=std::make_shared<EditSession>();t->journal=s->journal;auto sb=s->state(),tb=t->state();s->journal->beginGroup();s->change("Batch",[&]{s->settings.division=32;});t->change("Batch",[&]{t->settings.division=16;});s->journal->endGroup();s->undo();check(s->state()==sb&&t->state()==tb,"Multi-event operation undo restores every session");s->redo();check(s->settings.division==32&&t->settings.division==16,"Multi-event operation redo restores every session");
 s->journal->beginGroup(true);s->loadProjectReference({{a,0,2,0}},"Async reference");waitSession(s);auto completed=s->state();s->change("Theme after render",[&]{s->lightTheme=!s->lightTheme;});s->undo();check(s->state()==completed,"A control edit after worker completion is a separate undo step");

}
